// Поводы напоминания на день рассылки (по Варшаве): сезон шин — весной летние (15.03–30.04), осенью
// зимние (1.10–30.11), повод — сезон года; ТО — через 11 месяцев после последней Записи Клиента (в SQL).
// today (YYYY-MM-DD) — ручной запуск как будто в другой день; по расписанию — сегодня.
const TIME_ZONE = 'Europe/Warsaw';
const TYRE_SEASONS = [
  { season: 'spring', from: '03-15', to: '04-30' },
  { season: 'autumn', from: '10-01', to: '11-30' },
];
const today = $json.body?.today;
const day = today ? DateTime.fromISO(today, { zone: TIME_ZONE }) : DateTime.now().setZone(TIME_ZONE);
if (!day.isValid) throw new Error(`Неверный день рассылки: ${today}`);
const monthDay = day.toFormat('MM-dd');
const tyres = TYRE_SEASONS.find(({ from, to }) => from <= monthDay && monthDay <= to);
return { json: { day: day.toISODate(), tyres_campaign: tyres ? `tyres:${day.year}-${tyres.season}` : '' } };

// Напоминание на языке Беседы: шаблоны WhatsApp одобрены у Meta на pl и en (docs/whatsapp-setup.md),
// текст SMS — те же два языка. SMS говорит, как отказаться: STOP в Канале, откуда Клиент писал.
const TEMPLATES = {
  service: 'service_reminder',
  'tyres-spring': 'summer_tyres_reminder',
  'tyres-autumn': 'winter_tyres_reminder',
};
const TEXTS = {
  pl: {
    service: (company) => `${company}: od ostatniej wizyty minął prawie rok — czas na przegląd. Zapraszamy!`,
    'tyres-spring': (company) => `${company}: zbliża się sezon opon letnich — zapraszamy na wymianę.`,
    'tyres-autumn': (company) => `${company}: zbliża się sezon opon zimowych — zapraszamy na wymianę.`,
    stop: (place) => `Nie chcesz takich przypomnień? Napisz STOP na ${place}.`,
    places: { messenger: 'Messengerze', instagram: 'Instagramie' },
  },
  en: {
    service: (company) => `${company}: it has been almost a year since your last visit — time for a service.`,
    'tyres-spring': (company) => `${company}: summer tyre season is coming — book your tyre change with us.`,
    'tyres-autumn': (company) => `${company}: winter tyre season is coming — book your tyre change with us.`,
    stop: (place) => `Don't want these reminders? Write STOP on ${place}.`,
    places: { messenger: 'Messenger', instagram: 'Instagram' },
  },
};

// Повод «service:<Запись>» или «tyres:<год>-<сезон>» → вид напоминания.
function kind(campaign) {
  return campaign.startsWith('service:') ? 'service' : `tyres-${campaign.split('-').at(-1)}`;
}

// Postgres-узел без строк отдаёт один item без полей — напоминать некому.
return $input.all().filter((item) => item.json.campaign).map(({ json: r }) => {
  const texts = TEXTS[r.language === 'pl' ? 'pl' : 'en'];
  const k = kind(r.campaign);
  const place = texts.places[r.channel];
  return {
    json: {
      company_id: r.company_id,
      channel: r.channel,
      sender_id: r.sender_id,
      campaign: r.campaign,
      conversation_id: r.conversation_id,
      text: place ? `${texts[k](r.company)} ${texts.stop(place)}` : texts[k](r.company),
      template: { name: TEMPLATES[k], parameters: [] },
    },
  };
});
